  check('name').optional().isLength({ max: 50 }).trim().escape().withMessage('Name must be less than 50 characters'),
  check('email').optional().isEmail().normalizeEmail().withMessage('Invalid email format'),
  validateRequest
], (req, res) => {
  // Filter users based on validated query parameters
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' }
  ];

  const { id, name, email } = req.query;
  let filteredUsers = users;

  if (id) {
    filteredUsers = users.filter(user => user.id === parseInt(id));
  }
  if (name) {
    filteredUsers = users.filter(user => user.name === name);
  }
  if (email) {
    filteredUsers = users.filter(user => user.email === email);
  }

  res.json(filteredUsers);
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ error: 'Internal server error' });
});

// Start secure server
app.listen(PORT, () => {
  console.log(`Server running securely on port ${PORT}`);
});

module.exports = app;

